discrete InputSignalProcessing
port:
    event input real ReceiveRFSignal;
    event output real SendPreprocessedSignal;
state:
    initial state State1
        when entry() then
            statehold(5);
        end;

        when receive(ReceiveRFSignal) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(5);
        end;

        when timeover() then
            transition(State3);
        end;
    end;

    state State3
        when entry() then
            statehold(5);
        end;

        when timeover() then
            transition(State4);
        end;
    end;

    state State4
        when entry() then
            statehold(5);
        end;

        when timeover() then
            out
                send(SendPreprocessedSignal, 1);
            transition(State1);
        end;
    end;
end;
end;

